// Import starts empty. Only explicitly saved drafts survive reopening.
const draftKey='daynest-import-drafts-v1';
function readDrafts(){try{const rows=JSON.parse(localStorage.getItem(draftKey)||'[]');return Array.isArray(rows)?rows.filter(d=>typeof d.id==='string'&&typeof d.text==='string'):[]}catch{return []}}
function writeDrafts(rows){try{localStorage.setItem(draftKey,JSON.stringify(rows));return true}catch{toast('草稿保存失败，请检查浏览器存储权限。');return false}}
function clearImport(){ $('importText').value=''; $('importPreview').innerHTML=''; $('confirmImport').classList.add('hidden'); candidates=[]; parsedText=''; }
const draftArea=document.createElement('section');draftArea.style.cssText='border-top:1px solid #e1e6da;margin-top:20px;padding-top:16px';draftArea.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between"><h3 style="font-size:14px">我的草稿</h3><button type="button" class="notification" id="saveDraft">保存为草稿</button></div><p class="subtitle" style="line-height:1.8">仅保存原始文字，载入后重新识别日期。草稿保存在当前浏览器。</p><div id="draftList"></div>';$('importPreview').before(draftArea);
function renderDrafts(){const rows=readDrafts();$('draftList').innerHTML=rows.length?rows.map(d=>`<div style="display:flex;align-items:center;gap:10px;border-bottom:1px solid #e1e6da;padding:12px 0"><div style="flex:1;min-width:0"><div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px">${esc(d.text.slice(0,70))}</div><small class="subtitle">${esc(new Date(d.createdAt).toLocaleString('zh-CN'))}</small></div><button type="button" data-load-draft="${esc(d.id)}">载入</button><button type="button" data-delete-draft="${esc(d.id)}" style="color:#b96559">删除</button></div>`).join(''):'<p class="subtitle" style="padding:12px 0">还没有草稿。需要保留时，点击「保存为草稿」。</p>'}
importButton.onclick=()=>{clearImport();renderDrafts();importDialog.showModal();$('importText').focus()};
importDialog.addEventListener('close',clearImport);
$('saveDraft').onclick=()=>{const text=$('importText').value.trim();if(!text){toast('请先输入要保存的文字');return}const rows=readDrafts();if(rows.some(d=>d.text===text)){toast('相同内容的草稿已保存');return}rows.unshift({id:crypto.randomUUID(),text,createdAt:new Date().toISOString()});if(writeDrafts(rows)){renderDrafts();toast('草稿已保存，下次可从草稿载入')}};
draftArea.addEventListener('click',e=>{const load=e.target.closest('[data-load-draft]'),del=e.target.closest('[data-delete-draft]');if(load){const draft=readDrafts().find(d=>d.id===load.dataset.loadDraft);if(!draft)return;if($('importText').value.trim()&&!confirm('载入草稿会替换当前文字，是否继续？'))return;clearImport();$('importText').value=draft.text;$('importText').focus();toast('草稿已载入，请点击「识别日程」')}if(del){if(!confirm('确定删除这份草稿吗？'))return;const rows=readDrafts().filter(d=>d.id!==del.dataset.deleteDraft);if(writeDrafts(rows)){renderDrafts();toast('草稿已删除')}}});
function deleteSchedule(id){const item=events.find(e=>e.id===id);if(!item)return;if(!confirm(`确定删除「${item.title}」吗？`))return;const previous=events;events=events.filter(e=>e.id!==id);if(!save()){events=previous;return}render();toast('日程已删除')}
const originalRender=render;
render=function(){originalRender();document.querySelectorAll('#schedule [data-edit]').forEach(edit=>{const b=document.createElement('button');b.type='button';b.textContent='删除';b.style.color='#b96559';b.dataset.removeEvent=edit.dataset.edit;edit.before(b)});document.querySelectorAll('#listBody [data-edit]').forEach(row=>{const b=document.createElement('button');b.type='button';b.textContent='删除';b.style.cssText='margin-left:auto;color:#b96559;flex-shrink:0;padding:10px';b.dataset.removeEvent=row.dataset.edit;row.append(b)})};
document.addEventListener('click',e=>{const b=e.target.closest('[data-remove-event]');if(b){e.stopImmediatePropagation();deleteSchedule(b.dataset.removeEvent)}},true);
render();
